CREATE COLUMN TABLE "TEST_AP"."OSLT" ("SltCode" INTEGER CS_INT NOT NULL , "ItemCode" NVARCHAR(50), "StatusNum" INTEGER CS_INT, "Owner" INTEGER CS_INT, "CreatedBy" INTEGER CS_INT, "DateCreate" LONGDATE CS_LONGDATE, "UpdateBy" INTEGER CS_INT, "DateUpdate" LONGDATE CS_LONGDATE, "Subject" NVARCHAR(254), "Symptom" NVARCHAR(254), "Cause" NVARCHAR(254), "Descriptio" NCLOB MEMORY THRESHOLD 1000, "Attachment" NCLOB MEMORY THRESHOLD 1000, "AtcEntry" INTEGER CS_INT, "Transfered" NVARCHAR(1) DEFAULT 'N', "Instance" SMALLINT CS_INT DEFAULT 0, PRIMARY KEY ("SltCode")) UNLOAD PRIORITY 5  AUTO MERGE 